namespace mp = fizmo::multiprecision;
namespace ftim = fizmo::time;
typedef mp::BigFloat (*big_const_fn)();


template <typename T>
inline fizmo::fizmo_float_from_int_t<T> ms_of(const ftim::Stopwatch<T>& sw) {
    using F = fizmo::fizmo_float_from_int_t<T>;
    return F(sw.elapsed_nanoseconds().count()) / F(1000000);
}

template <typename T>
void test_mp(std::ofstream& out, const std::string& name, const T& calculated_value, const std::string& true_value) {
    out << name << ":\n" << calculated_value << "\n" << true_value << "\n\n";
}

