inline std::size_t leading_match(const char* got, const char* want) {
    std::size_t digits = 0;

    for (std::size_t i = 0; got[i] != '\0' && want[i] != '\0'; ++i) {
        if (got[i] != want[i]) break;
        if (got[i] >= '0' && got[i] <= '9') ++digits;
    }

    return digits;
}

template <typename T>
inline void report(
    std::ofstream& out, 
    const char* name, 
    const std::string& got, 
    const char* want, 
    std::size_t dps,
    T cold_ms,
    T warm_ms, 
    const char* note = ""
) {
    const std::size_t match = leading_match(got.c_str(), want);

    out << name << ":\n"
        << got  << "\n"
        << want << "\n"
        << "matched " << match << " / " << dps << " digits\n"
        << "Cold (ms): " << cold_ms << "\n"
        << "Warm (ms): " << warm_ms << "\n"
        << note
        << (match + 2 < dps ? "   [FAIL]" : "")
        << "\n\n";
}

