template <typename T>
void test_math_consts(std::ofstream& out) {
    const std::size_t dps = static_cast<std::size_t>(static_cast<long double>(T::mantissa_bits) * 0.301029995663981195213738894724L);
    out << "=== floatmp constants @ " << T::mantissa_bits << " mantissa bits (" << dps << " dps) ===\n\n";
    std::size_t tbl_n = 0;
    const float_const_entry<T>* tbl = float_const_table<T>(tbl_n);
    std::size_t ref_n = 0;
    const const_ref* refs = references(ref_n);
    std::size_t worst   = dps;
    const char* worst_n = "";
    std::size_t skipped = 0;
    T cold(0);
    T warm(0);

    for (std::size_t i = 0; i < ref_n; ++i) {
        const T& (*fn)() = nullptr;

        for (std::size_t j = 0; j < tbl_n; ++j) {
            if (std::strcmp(tbl[j].name, refs[i].name) == 0) { fn = tbl[j].fn; break; }
        }

        if (fn == nullptr) {
            out << refs[i].name << ": SKIPPED (no floatmp implementation)\n\n";
            ++skipped;
            continue;
        }

        ftim::Stopwatch<fizmo::fizmo_int_from_float_t<T>> sw;
        sw.start();
        const T& first = fn();
        sw.stop();
        cold = ms_of(sw);

        sw.restart();
        const T& second = fn();
        sw.stop();
        warm = ms_of(sw);

        const bool cached = (&first == &second);
        const std::string got = first.to_string();

        report(
            out, refs[i].name, 
            got, refs[i].digits, 
            dps, cold, warm,
            cached ? "" : "   [NOT CACHED: second call returned a different object]"
        );
    }

    out << "--- summary ---\n"
        << "constants checked: " << (ref_n - skipped) << " (skipped " << skipped << ")\n"
        << "worst match:       " << worst << " digits (" << worst_n << ")\n"
        << "cold:              " << cold << "\n"
        << "warm:              " << warm << "\n\n";
}

