static big_const_fn find_big_const(const char* name) {
    const std::size_t n = sizeof(g_big_consts) / sizeof(g_big_consts[0]);

    for (std::size_t i = 0; i < n; ++i) {
        if (std::strcmp(g_big_consts[i].name, name) == 0) return g_big_consts[i].fn;
    }

    return nullptr;
}

void test_big_math_consts(std::ofstream& out, std::size_t bits) {
    using internal_int = mp::int128;
    using internal_float = fizmo::fizmo_float_from_int_t<internal_int>;
    const mp::ScopedContext scope(bits);
    const mp::BigFloatContext& ctx = mp::BigFloatContext::current();
    const std::size_t dps = ctx.dps();
    out << "=== BigFloat constants @ " << ctx.precision << " bits (" << dps << " dps) ===\n\n";
    std::size_t count = 0;
    const const_ref* refs = references(count);
    std::size_t worst   = dps;
    const char* worst_n = "";
    std::size_t skipped = 0;

    for (std::size_t i = 0; i < count; ++i) {
        const big_const_fn fn = find_big_const(refs[i].name);

        if (fn == nullptr) {
            out << refs[i].name << ": SKIPPED (no BigFloat implementation)\n\n";
            ++skipped;
            continue;
        }

        ftim::Stopwatch<internal_int> sw;

        sw.start();
        const mp::BigFloat first = fn();
        sw.stop();
        const internal_float cold = ms_of(sw);
        
        sw.restart();
        const mp::BigFloat second = fn();  
        sw.stop();
        const internal_float warm = ms_of(sw);

        const std::string got   = first.to_string();
        const bool        stable = (second.compare(first) == mp::BigFloat::ordering::equal);
        const std::size_t match  = leading_match(got.c_str(), refs[i].digits);

        if (match < worst) { worst = match; worst_n = refs[i].name; }

        out << refs[i].name << ":\n"
            << got << "\n"
            << refs[i].digits << "\n"
            << "matched " << match << " / " << dps << " digits"
            << (stable ? "" : "   [UNSTABLE: repeat call differs]")
            << (match + 2 < dps ? "   [FAIL]" : "")
            << "\nCold: " << cold << "\nWarm: " << warm << "\n\n";
    }

    out << "--- summary ---\n"
        << "constants checked: " << (count - skipped) << " (skipped " << skipped << ")\n"
        << "worst match:       " << worst << " digits (" << worst_n << ")\n\n";
}

int main() {
    using test_float = mp::StandardFloat<1 << 10>;
    std::ofstream out("output.txt"); 

    if (!out) {
        std::cerr << "Failed to open output.txt\n";
        return 1;
    }

    std::cout << std::fixed << std::setprecision(15) << std::boolalpha;
    out << std::fixed << std::setprecision(15) << std::boolalpha;
    ftim::Stopwatch sw;
    mp::BigFloatContext global;
    global.set_current(mp::BigFloatContext::with_dps(8320));

    const std::string truth = "-3....";
    test_mp(out, "gamma", mp::math::gamma(mp::BigFloat("-0.5")), truth);

    sw.start();
    test_mp(out, "gamma", mp::math::gamma(mp::BigFloat("-0.5")), truth);
    sw.stop();
    out << sw.exact_elapsed_milliseconds() << "ms\n";

    out.close();
}